const prices = [6, 15, 9];
const doubled = prices.map(p => p * 2);
console.log(doubled);

const scores = [34, 67, 52, 41, 90];
const passing = scores.filter(s => s >= 50);
console.log(passing);

const cart = [
  { name: "Boba", price: 6.5 },
  { name: "Notebook", price: 12 },
  { name: "Pen", price: 2.5 }
];
const total = cart.reduce((sum, item) => sum + item.price, 0);
console.log("Total: " + total);

